ALTER TABLE conversations ADD COLUMN project_id TEXT REFERENCES projects(id) ON DELETE CASCADE;
-- One interview thread per project; serves GetInterviewThread.
CREATE UNIQUE INDEX IF NOT EXISTS idx_conversations_interview ON conversations(project_id) WHERE project_id IS NOT NULL;
-- Workspaces seeded before the Interview play existed get it here; new workspaces get it from SeedDefaults.
INSERT INTO plays (id, workspace_id, label, type, description, instructions, enabled, show_when_stage, excluded_project_ids, created_by, created_at, updated_at)
SELECT lower(hex(randomblob(16))), w.id, 'Interview', 'interview', 'Asks one question at a time to record this project''s rules for agents, and amends them on a re-run.', 'Run this project''s interview, the conversation that records its rules for agents; the project and the answers it already records are named below. Start by calling `memory_create_interview` with the project id: it returns the interview memory, created from the workspace''s Interview template the first time. If the memory already holds rules, this is a re-run: amend it, never start over. Ask first what has changed, keep every rule that still holds, and change only what the answers change. Ask one question at a time with your question tool, never a batch, and give every question your recommended answer as its first option, labelled (Recommended), so the person can accept it or type their own. Your first question asks whether to scan the codebase for answers first. If they say yes, read the checkout you are running in (manifests and lockfiles, CI config, linter and formatter config, tests, README, docs and decision records), draft an answer for each category, then grill them on it: one question per finding, saying what you found and where, until each is confirmed or corrected. Never record a finding they have not confirmed. Work through the categories in the interview''s headings in order. Do not ask again what the project already records, such as where its tests live, unless the person changes it; record a change there with `project_set_tests_location` as well. Save the interview with `memory_update` after each category, passing its id, title, when-to-use, and the full markdown body, so progress survives a stop. Write rules, not a transcript: short imperative lines under each heading, with no questions, answers, or narration. Replace each heading''s prompt line with its rules, and leave out a heading the project has no rule for. The body is capped at 8,000 characters of markdown and every agent turn in the project carries it in full, so keep it well under the cap: tighten wording and drop what a linter or the code already enforces. Reply with a short summary of what the interview now says and what this run changed.', 1, NULL, '[]', '', strftime('%s','now'), strftime('%s','now')
FROM workspaces w
WHERE NOT EXISTS (SELECT 1 FROM plays p WHERE p.workspace_id = w.id AND p.type = 'interview');
